tos_alpha:dwell_time:berth:
with num_agg as (
  select berth_allocations.berth as berth, sum(date_diff('hour', gate_in, gate_out)) as value from container_events left join berth_allocations on container_events.call_id = berth_allocations.call_id and berth_allocations.terminal = ? where container_events.terminal = ? and container_events.deleted = false and container_events.gate_in >= ? and container_events.gate_in < ? group by 1
),
denom_agg as (
  select berth_allocations.berth as berth, count(container_id) as value from container_events left join berth_allocations on container_events.call_id = berth_allocations.call_id and berth_allocations.terminal = ? where container_events.terminal = ? and container_events.deleted = false and container_events.gate_in >= ? and container_events.gate_in < ? group by 1
)
select num_agg.berth, num_agg.value as numerator, denom_agg.value as denominator, num_agg.value * 1.0 / denom_agg.value as value
from num_agg join denom_agg using (berth)

tos_beta:crane_idle_pct:equipment_type:
with num_agg as (
  select split_part(equipment_id, '-', 1) as equipment_type, sum(duration_hours) as value from equipment_downtime where equipment_downtime.terminal = ? and equipment_downtime.event_time >= ? and equipment_downtime.event_time < ? group by 1
),
denom_agg as (
  select split_part(equipment_id, '-', 1) as equipment_type, count(distinct equipment_id) as value from equipment_downtime where equipment_downtime.terminal = ? and equipment_downtime.event_time >= ? and equipment_downtime.event_time < ? group by 1
)
select num_agg.equipment_type, num_agg.value as numerator, denom_agg.value as denominator, num_agg.value * 1.0 / denom_agg.value as value
from num_agg join denom_agg using (equipment_type)
